'use strict';
const difficultyModes=[
 {name:'NORMAL',label:'노멀',slots:5,hp:1,damage:1,speed:1,spawn:1,projectile:1,bossHp:1,cooldown:1,gold:1,xp:1},
 {name:'HARD',label:'하드',slots:3,hp:1.15,damage:1.2,speed:1.08,spawn:1.1,projectile:1.08,bossHp:1.1,cooldown:.9,gold:1.3,xp:1.1},
 {name:'EXTREME',label:'익스트림',slots:1,hp:1.25,damage:1.4,speed:1.15,spawn:1.15,projectile:1.15,bossHp:1.15,cooldown:.8,gold:1.6,xp:1.2}
];
const ranksV3=['훈련병','정규군','베테랑','엘리트'];
let selectedDifficulty=0,accountProfile=null,accountReady=false,accountBusy=false,pendingOperation=null,marketPolling=false,accountSyncing=false,serverOffset=0;
function modeRules(){return difficultyModes[view==='battle'&&run?run.difficulty:selectedDifficulty]}
const originalCamp=renderCamp,originalStore=renderStore,originalShop=renderShop;
function accountStatus(message){$('saveNote').textContent=message;const status=$('accountStatus');if(status)status.textContent=message}
function updateAccountControls(){const locked=!accountReady||accountBusy||!!pendingOperation;document.body.classList.toggle('account-pending',locked);for(const id of ['rankSubmit','recoveryIssue','redeemGold'])if($(id))$(id).disabled=locked;if($('rocketLaunch'))$('rocketLaunch').disabled=locked||!!accountProfile?.active||save.gold<100;if($('plinkoDrop'))$('plinkoDrop').disabled=locked||!!accountProfile?.active||save.gold<100;if($('rocketCashout'))$('rocketCashout').disabled=locked||accountProfile?.active?.kind!=='rocket';$('start').disabled=locked||!!accountProfile?.active||!assetsReady;document.querySelectorAll('[data-upgrade],[data-weapon],[data-cosmetic-buy],[data-reset],[data-title-buy],[data-title-equip],#claimTitles,#clearTitle').forEach(b=>{if(locked||accountProfile?.active)b.disabled=true});if($('retryAccount'))$('retryAccount').hidden=!pendingOperation&&accountReady;if($('abortActive'))$('abortActive').hidden=!accountProfile?.active||accountProfile.active.kind==='plinko'}
function applyProfile(p){if(!p)return;if(p.titlesUnchanged){const previous=accountProfile?.id===p.id?accountProfile:null;p={...p,titles:previous?.titles||{owned:[],eligible:[],best:{},equipped:null},titleCheckedAt:previous?.titleCheckedAt||0};delete p.titlesUnchanged}if(accountProfile&&p.id===accountProfile.id&&p.revision===accountProfile.revision&&(p.titleCheckedAt||0)<(accountProfile.titleCheckedAt||0))return;if(accountProfile&&p.id===accountProfile.id&&p.revision<accountProfile.revision)return;if(accountProfile&&accountProfile.id!==p.id)window.realtimeReset?.();accountProfile=p;accountReady=true;save={...p,unlocked:0,clears:[]};selectCampaign();persist();accountStatus('서버 저장 완료 · '+ranksV3[p.rank]+' · '+p.gold.toLocaleString()+' G');updateAccountControls()}
function selectCampaign(){save.clears=accountProfile?.campaigns[selectedDifficulty]||[];save.unlocked=Math.min(9,save.clears.length?Math.max(...save.clears)+1:0);selected=Math.min(selected,save.unlocked)}
async function accountFetch(path,data){if(window.realtimeReady?.()&&['operation','status','titles'].includes(path)&&data?.action!=='recovery'){try{return await window.realtimeRequest(path,data)}catch(e){if(e.status&&e.status<500)throw e;/* Retry the same durable operation ID over HTTP. */}}const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),12000);try{const response=await fetch('/api/v3/'+path+((path==='status'||path==='operation'&&['sync','rocket','plinko','cashout','exploreStart','exploreStep','exploreReturn'].includes(data?.action))?'?compact=1':''),{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data),signal:controller.signal});const json=await response.json();if(Number.isFinite(json.serverNow))serverOffset=json.serverNow-Date.now();if(!response.ok)throw Object.assign(Error(json.error||'서버 오류'),{status:response.status});return json}finally{clearTimeout(timeout)}}
function savePending(){try{if(pendingOperation)sessionStorage.setItem('sector09-v3-pending',JSON.stringify(pendingOperation));else sessionStorage.removeItem('sector09-v3-pending')}catch{}}
async function sendPending(){if(!pendingOperation||accountBusy)return null;accountBusy=true;accountStatus('서버 확인 중…');updateAccountControls();try{const result=await accountFetch('operation',pendingOperation);applyProfile(result.profile);pendingOperation=null;savePending();return result}catch(e){if(e.status&&e.status<500){pendingOperation=null;savePending()}else accountReady=false;accountStatus('처리 확인 필요 · 다시 연결을 누르면 같은 요청을 확인합니다.');toast(e.message||'연결이 끊겼습니다. 다시 연결해 주세요.');return null}finally{accountBusy=false;updateAccountControls()}}
async function transact(action,fields={}){if(!accountReady||accountBusy||pendingOperation){toast('먼저 서버 연결과 이전 요청을 확인해 주세요.');return null}pendingOperation={id:crypto.randomUUID(),action,...fields};savePending();return sendPending()}
async function syncAccount(){if(accountBusy||accountSyncing)return;accountSyncing=true;try{if(pendingOperation){const action=pendingOperation.action,result=await sendPending();if(!result)return;if(action==='finish')renderSettlement(result.result.settlement);if(action==='start'&&result.result.run)try{sessionStorage.setItem('sector09-v3-live-run',result.result.run.id)}catch{};if(action==='recovery'&&result.result.code)showRecoveryCode(result.result.code)}const data=await accountFetch('session',{});applyProfile(data.profile);const synced=await transact('sync');if(synced)restoreActive();renderCamp();if(view==='shop')renderShop();if(view==='store')renderStore()}catch(e){accountReady=false;accountStatus('서버에 연결하지 못했습니다. 잔액을 변경하지 않았습니다.');toast(e.message)}finally{accountSyncing=false}updateAccountControls()}
renderCamp=function(){selectCampaign();originalCamp();if(!$('difficultyPanel')){const panel=document.createElement('section');panel.id='difficultyPanel';panel.className='difficulty-panel';$('stages').before(panel)}const rank=accountProfile?.rank??0;$('difficultyPanel').innerHTML='<div class="commander-row"><span class="rank-badge rank-'+rank+'">'+ranksV3[rank]+'</span>'+titleBadge(accountProfile?.titles?.equipped)+'<small>캠페인 3개 · 공통 골드와 연구</small></div><div class="difficulty-tabs">'+difficultyModes.map((m,i)=>'<button data-mode="'+i+'" class="'+(selectedDifficulty===i?'active':'')+'" '+(i>0&&(accountProfile?.campaigns[i-1].length??0)<10?'disabled':'')+'>'+m.name+'<small>'+m.slots+'종 무기 · '+(accountProfile?.campaigns[i].length??0)+'/10</small></button>').join('')+'</div><label>시작 무기 <select id="startWeapon" '+(selectedDifficulty===0?'disabled':'')+'>'+weapons.map(w=>'<option value="'+w.id+'">'+w.name+'</option>').join('')+'</select></label><p>'+(['돌격 소총으로 출정 · 최대 5종의 무기를 조합하세요.','시작 무기 선택 · 최대 3종으로 돌파하세요.','무기 1종 · 레벨 3/5/7/9 자동 성장 · 패시브만 선택'][selectedDifficulty])+'</p>';$('startWeapon').value=selectedDifficulty===0?'gauss':accountProfile?.lastWeapon||'gauss';$('difficultyPanel').querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{selectedDifficulty=+b.dataset.mode;selected=0;renderCamp();preloadRankings()});$('reward').textContent=Math.floor(stages[selected].reward*difficultyModes[selectedDifficulty].gold)+' G';$('bossIntel').textContent=stages[selected].boss+' · '+bossPatternTip(selected,selectedDifficulty);drawPreview();updateAccountControls()};
let storeSection='appearance';
renderShop=function(){originalShop();updateAccountControls()};
renderStore=function(){
 if(!$('storeSections')){
  const tabs=document.createElement('div');tabs.id='storeSections';tabs.className='store-section-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','상점 분류');
  tabs.innerHTML='<button id="appearanceSection" role="tab" aria-controls="storeItems">외형</button><button id="titleSection" role="tab" aria-controls="storeItems">칭호</button>';$('storeItems').before(tabs);
  for(const [id,section]of [['appearanceSection','appearance'],['titleSection','titles']]){const b=$(id);b.onclick=()=>{storeSection=section;renderStore();if(section==='titles')refreshLiveTitles()};b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const target=e.key==='Home'?'appearanceSection':e.key==='End'?'titleSection':id==='appearanceSection'?'titleSection':'appearanceSection';$(target).click();$(target).focus()}}}
 }
 for(const [id,section]of [['appearanceSection','appearance'],['titleSection','titles']]){$(id).setAttribute('aria-selected',String(storeSection===section));$(id).tabIndex=storeSection===section?0:-1}
 $('storeItems').setAttribute('role','tabpanel');$('storeItems').setAttribute('aria-labelledby',storeSection==='appearance'?'appearanceSection':'titleSection');
 if(storeSection==='appearance')originalStore();else{
  renderTitleCollection();
 }updateAccountControls();
};
buy=async id=>{const r=await transact('buy',{category:'research',item:id});if(r){renderShop();toast('병사 연구 완료')}};
buyWeapon=async id=>{const r=await transact('buy',{category:'weapon',item:id});if(r){renderShop();toast('무기 연구 완료')}};
buyCosmetic=async id=>{const r=await transact('buy',{category:'cosmetic',item:id});if(r){renderStore();toast('외형 구매 · 장착 완료')}};
equipCosmetic=async(category,id)=>{if(await transact('equip',{category,item:id}))renderStore()};
async function start(){if(!assetsReady)return toast('전투 에셋을 불러오는 중입니다.');const result=await transact('start',{difficulty:selectedDifficulty,stage:selected,weapon:$('startWeapon').value,combatRules:2});if(!result)return;try{sessionStorage.setItem('sector09-v3-live-run',result.result.run.id)}catch{}selected=result.result.run.stage;selectedDifficulty=result.result.run.difficulty;beginLocalRun(result.result.run);$('battleStage').textContent=difficultyModes[run.difficulty].name+' · '+stages[run.stage].name}
$('start').onclick=start;
async function end(win,retreat=false){if(!run||run.ended)return;run.ended=true;run.paused=true;run.modalMode='result';run.bossZones=[];run.hostile=[];for(const e of run.enemies)if(e.type===3)e.dead=true;$('bossBar').hidden=true;openModal('<h2>작전 종료 · 정산 확인 중</h2><p>획득 골드는 서버 확인 후 잔액에 반영됩니다.</p>'+damageReport(run)+'<button id="retrySettlement">정산 다시 확인</button>');$('retrySettlement').onclick=syncAccount;const fields={runId:run.serverId,outcome:win?'clear':retreat?'retreat':'lose',elapsedMs:Math.round(run.t*1000),kills:run.kills,killTypes:run.killTypes,goldChests:run.goldChests,goldSupplies:run.goldSupplies,wealthLedger:run.wealthLedger,weapons:run.weapons,skills:Object.fromEntries(Object.entries(run.skills).filter(([,v])=>v)),level:run.level};const result=await transact('finish',fields);if(result){run.finishId=result.result.settlement.finishId;renderSettlement(result.result.settlement)}}
function renderSettlement(s){if(!s)return;try{sessionStorage.removeItem('sector09-v3-live-run')}catch{};const win=s.outcome==='clear';openModal('<div class="eyebrow">'+(win?'MISSION COMPLETE':'MISSION RESULT')+'</div><h2>'+(win?'작전 성공. 귀환을 환영합니다.':'전투 기록을 저장했습니다.')+'</h2>'+(s.promoted?'<p class="rank-badge rank-'+accountProfile.rank+'">진급 · '+ranksV3[accountProfile.rank]+'</p><p>'+(accountProfile.rank===1?'하드 1~10단계가 해금되었습니다.':accountProfile.rank===2?'익스트림 1~10단계가 해금되었습니다.':'모든 난이도를 완주했습니다.')+'</p>':'')+'<div class="result-stats"><div><b>'+timeLabel(s.elapsedMs||0)+'</b><small>생존 시간</small></div><div><b>'+(s.kills||0)+'</b><small>처치</small></div><div><b>+'+(s.paid||0).toLocaleString()+' G</b><small>서버 정산 완료</small></div></div>'+(win?'<div id="clearRank"></div>':'')+(run?.serverId===s.id?damageReport(run):'')+'<div class="modal-actions"><button id="toShop">무기고에서 강화</button><button id="toCamp">작전 선택</button></div>');$('toShop').onclick=()=>{closeModal();show('shop')};$('toCamp').onclick=()=>{closeModal();show('camp')};if(win)clearRanking(s)}
function restoreActive(){const a=accountProfile.active;if(!a){window.marketActive=false;if(accountProfile.lastSettlement?.kind!=='run')renderMarketSettlement(accountProfile.lastSettlement);return}if(a.kind==='run'){if(run?.serverId===a.id&&!run.ended)return;let reloadId;try{reloadId=sessionStorage.getItem('sector09-v3-live-run')}catch{}if(reloadId===a.id){transact('abort',{activeId:a.id}).then(r=>{if(r){sessionStorage.removeItem('sector09-v3-live-run');accountStatus('새로고침으로 중단된 출정을 종료했습니다.');renderCamp()}})}else accountStatus('다른 창 또는 중단된 출정이 있습니다. 내 데이터에서 종료할 수 있습니다.');return}show('market');window.marketActive=false;selectMarketGame(a.kind);if(a.kind==='rocket'){Object.assign(rocket,{state:'flying',id:a.id,bet:a.bet,mult:1,crash:Infinity,started:rocketNow()-(Date.now()+serverOffset-a.started)});rocketLock(true);$('rocketCanvas').parentElement.classList.remove('crashed','collected');$('rocketPhase').textContent='상승 중';$('rocketStatus').textContent='폭발 전에 수령하세요 · 수령은 서버 도착 기준'}else{Object.assign(plinko,{state:'falling',id:a.id,bet:a.bet,steps:a.bits,started:rocketNow()-(Date.now()+serverOffset-a.started),slot:-1});plinkoControls(true)}scheduleMarketPoll()}
rocketLaunch=async()=>{if(view!=='market')return;const bet=Number($('rocketBet').value);if(!Number.isSafeInteger(bet)||bet<100||bet>100000)return toast('100~100,000 G를 입력하세요.');await arcadeRequest('rocket',{bet},'rocketLaunch','발사 요청 중…',restoreActive)};
dropPlinko=async()=>{if(view!=='market')return;const bet=Number($('plinkoBet').value);if(!Number.isSafeInteger(bet)||bet<100||bet>100000)return toast('100~100,000 G를 입력하세요.');await arcadeRequest('plinko',{bet},'plinkoDrop','낙하 요청 중…',restoreActive)};
rocketUpdate=function(now){if(rocket.state!=='flying')return;rocket.mult=Math.exp(.13*Math.max(0,now-rocket.started)/1000);$('rocketMultiplier').textContent=rocket.mult.toFixed(2)+'×';$('rocketPayout').textContent='예상 '+Math.floor(rocket.bet*rocket.mult).toLocaleString()+' G'};
rocketFinish=()=>{};finishPlinko=()=>{};updatePlinko=()=>{};
async function arcadeRequest(action,data,id,label,done){if(accountBusy||pendingOperation||!accountReady)return;const b=$(id),original=b.textContent,status=$(action==='plinko'?'plinkoStatus':'rocketStatus');b.textContent=label;b.setAttribute('aria-busy','true');status.textContent=label;try{const r=await transact(action,data);if(r)done(r);else status.textContent=pendingOperation?'연결 확인 필요 · 내 데이터에서 다시 연결하세요.':'요청을 완료하지 못했습니다. 다시 시도하세요.'}finally{b.textContent=original;b.removeAttribute('aria-busy');updateAccountControls()}}
async function cashoutServer(){if(accountBusy||pendingOperation||!accountReady||accountProfile?.active?.kind!=='rocket')return;rocket.state='confirming';$('rocketPhase').textContent='수령 확인 중';await arcadeRequest('cashout',{activeId:accountProfile?.active?.id},'rocketCashout','수령 요청 중…',r=>renderMarketSettlement(r.result.settlement||r.profile.lastSettlement));if(rocket.state==='confirming'&&!pendingOperation&&accountProfile?.active?.kind==='rocket')restoreActive()}
$('rocketLaunch').onclick=rocketLaunch;$('rocketCashout').onclick=cashoutServer;$('plinkoDrop').onclick=dropPlinko;
function renderMarketSettlement(s){if(!s||!['rocket','plinko'].includes(s.kind))return;const history=s.kind==='rocket'?rocket.history:plinko.history;if(!history.some(h=>h.id===s.id)){history.unshift({id:s.id,mult:s.multiplier||1,net:s.paid-s.bet,success:s.paid>0});history.splice(10)}$(s.kind==='rocket'?'rocketHistory':'plinkoHistory').innerHTML=history.map(h=>'<span class="'+(h.net>=0?'success':'failure')+'">'+h.mult.toFixed(2)+'× <small>'+h.net.toLocaleString()+' G</small></span>').join('');window.marketActive=false;if(s.kind==='rocket'){rocket.state=s.paid?'collected':'crashed';rocket.mult=s.multiplier||1;$('rocketMultiplier').textContent=rocket.mult.toFixed(2)+'×';$('rocketCanvas').parentElement.classList.add(rocket.state);rocketLock(false);$('rocketPhase').textContent=s.paid?'수령 완료':'미수령 종료';$('rocketStatus').textContent='서버 정산 완료';$('rocketResult').textContent=(s.multiplier||1).toFixed(2)+'× · 수령 '+s.paid.toLocaleString()+' G';$('rocketPayout').textContent=s.paid.toLocaleString()+' G'}else{plinko.state='landed';plinko.slot=s.slot;plinko.steps=s.bits||Array.from({length:16},(_,i)=>i<s.slot?1:0);plinkoControls(false);$('plinkoStatus').textContent='착지 · 서버 자동 정산 완료';$('plinkoPayout').textContent=s.paid.toLocaleString()+' G';$('plinkoResult').textContent=s.multiplier+'× · 수령 '+s.paid.toLocaleString()+' G';drawPlinkoSlots()}renderMarket();updateAccountControls()}
function scheduleMarketPoll(){if(marketPolling||window.realtimeReady?.())return;const a=accountProfile?.active;if(!a||a.kind==='run'||a.kind==='explore')return;marketPolling=true;const delay=a.kind==='plinko'?Math.max(100,a.ends-(Date.now()+serverOffset)+30):250;setTimeout(async()=>{try{if(!accountProfile?.active||accountProfile.active.id!==a.id)return;if(accountBusy||pendingOperation)return;const r=await accountFetch('status',{});applyProfile(r.profile);if(!accountProfile.active)renderMarketSettlement(accountProfile.lastSettlement)}catch{accountStatus('오락실 연결 확인 중 · 수령 요청은 서버 도착 시점에 판정됩니다.')}finally{marketPolling=false;scheduleMarketPoll()}},delay)}
function showRecoveryCode(code){$('recoveryResult').textContent='새 복구 코드 (이전 코드는 무효):\n'+code;const old=$('copyRecovery');if(old)old.remove();const b=document.createElement('button');b.id='copyRecovery';b.textContent='복구 코드 복사';b.onclick=async()=>{try{await navigator.clipboard.writeText(code);toast('복구 코드를 복사했습니다.')}catch{toast('코드 전체를 선택해 복사해 주세요.')}};$('recoveryResult').after(b);}
function openAccount(){if(view==='battle')pause();$('dataContent').innerHTML='<div class="eyebrow">PLAYER ACCOUNT</div><h2>내 데이터</h2><p id="accountStatus"></p><p>플레이어 ID: '+escapeHTML(accountProfile?.id||'연결 대기')+'<br>이 ID는 로그인 수단이 아닙니다.</p><div class="modal-actions"><button id="retryAccount">다시 연결 / 처리 확인</button><button id="recoveryIssue">복구 코드 새로 발급</button></div><pre id="recoveryResult" class="recovery-code"></pre><p>코드는 비밀번호처럼 보관하세요. 재발급 시 이전 코드는 즉시 무효가 됩니다. 연결된 브라우저와 복구 코드를 모두 잃으면 복구할 수 없습니다.</p><label>다른 플레이어 이어 하기<input id="recoveryInput" autocomplete="off" type="password" placeholder="S09-…"></label><button id="recoverPlayer">복구 코드로 연결</button><p>기존 저장 파일은 가져올 수 없습니다. 골드·장비는 서버 기록만 사용합니다.</p><button id="abortActive">중단된 게임 종료 (미정산 보상 없음)</button><form id="goldCodeForm"><label for="goldCode">골드 지급 코드</label><div class="rank-input"><input id="goldCode" type="password" autocomplete="off" placeholder="지급받은 코드 입력" required><button id="redeemGold" type="submit">코드 사용</button></div><p id="goldCodeStatus" role="status"></p></form><button id="closeData">닫기</button>';$('dataModal').showModal();$('closeData').onclick=()=>$('dataModal').close();$('goldCodeForm').onsubmit=async e=>{e.preventDefault();$('goldCodeStatus').textContent='지급 확인 중…';const r=await transact('redeemGold',{code:$('goldCode').value});if(r){$('goldCode').value='';$('goldCodeStatus').textContent='1,000,000 G 지급 완료';renderCamp();if(view==='shop')renderShop();if(view==='store')renderStore();if(view==='market')renderMarket()}else $('goldCodeStatus').textContent=pendingOperation?'연결 확인 필요 · 다시 연결로 처리 결과를 확인하세요.':'코드를 확인해 주세요. 이미 사용한 코드는 재사용할 수 없습니다.'};$('retryAccount').onclick=syncAccount;$('recoveryIssue').onclick=async()=>{const r=await transact('recovery');if(r)showRecoveryCode(r.result.code)};$('recoverPlayer').onclick=async()=>{if(accountBusy||pendingOperation||view==='battle'||accountProfile?.active)return toast('진행 중인 게임과 요청을 먼저 종료하세요.');accountBusy=true;try{const r=await accountFetch('recover',{code:$('recoveryInput').value});accountProfile=null;applyProfile(r.profile);$('recoveryInput').value='';selectedDifficulty=0;selected=0;renderCamp();toast('서버 기록에 연결했습니다.')}catch(e){toast(e.message)}finally{accountBusy=false;updateAccountControls()}};$('abortActive').onclick=async()=>{const r=await transact('abort',{activeId:accountProfile.active.id});if(r){window.marketActive=false;rocket.state='idle';plinko.state='idle';rocketLock(false);if(view==='battle'){closeModal();show('camp')}accountStatus('중단된 게임을 종료했습니다.')}};accountStatus(accountReady?'서버 연결됨':'연결 확인 필요');updateAccountControls()}
$('dataBtn').onclick=openAccount;$('importFile').disabled=true;
$('researchTab').onclick=()=>{armoryTab='research';renderShop()};$('weaponsTab').onclick=()=>{armoryTab='weapons';renderShop()};
// Rank filters are part of both request and cache identity.
requestRanking=function(stage,force=false,difficulty=selectedDifficulty,weapon='all'){const key=difficulty+':'+stage+':'+weapon;const cached=rankingCache.get(key);if(!force&&cached&&Date.now()-cached.at<30000)return Promise.resolve(cached.rows);const old=rankingRequests.get(key);if(old&&!force)return old.promise;if(old)old.controller.abort();const entry={controller:new AbortController()},timeout=setTimeout(()=>entry.controller.abort(),8000);entry.promise=(async()=>{try{const r=await fetch('/api/v3/rankings?stage='+stage+'&difficulty='+difficulty+'&weapon='+weapon,{signal:entry.controller.signal});const d=await r.json();if(!r.ok)throw Error(d.error);if(rankingRequests.get(key)===entry)rankingCache.set(key,{rows:d.rows,at:Date.now()});return d.rows}finally{clearTimeout(timeout);if(rankingRequests.get(key)===entry)rankingRequests.delete(key)}})();rankingRequests.set(key,entry);return entry.promise};
rankingRowsHTML=rows=>rows.length?'<div class="ranking-scroll"><table class="rank-table"><thead><tr><th>순위</th><th>플레이어</th><th>무기</th><th>클리어</th><th>처치</th></tr></thead><tbody>'+rows.map((r,i)=>'<tr><td>'+(i+1)+'</td><td><span class="rank-badge rank-'+r.rank+'">'+ranksV3[r.rank]+'</span> '+escapeHTML(r.nickname)+titleBadge(r.title)+'</td><td>'+r.weapons.map(w=>escapeHTML(weapons.find(x=>x.id===w.id)?.name||w.id)+(w.awake?' ✦':'')).join(' · ')+'</td><td>'+timeLabel(r.elapsedMs)+'</td><td>'+r.kills+'</td></tr>').join('')+'</tbody></table></div>':'<p>아직 등록된 클리어 기록이 없습니다.</p>';
loadRanking=async function(target,stage,force=false,difficulty=selectedDifficulty,weapon='all'){const root=$(target);if(!root)return;const identity={};root.rankRequest=identity;const cached=rankingCache.get(difficulty+':'+stage+':'+weapon);root.innerHTML=cached?rankingRowsHTML(cached.rows):'<p>랭킹을 불러오는 중…</p>';if(cached&&!force&&Date.now()-cached.at<30000)return;try{const rows=await requestRanking(stage,force,difficulty,weapon);if($(target)===root&&root.rankRequest===identity)root.innerHTML=rankingRowsHTML(rows)}catch{if(root.rankRequest!==identity)return;root.innerHTML=(cached?rankingRowsHTML(cached.rows):'')+'<p>최신 기록을 불러오지 못했습니다.</p>';const b=document.createElement('button');b.textContent='다시 시도';b.onclick=()=>loadRanking(target,stage,true,difficulty,weapon);root.append(b)}};
let rankingPreloadGeneration=0;preloadRankings=async function(){const generation=++rankingPreloadGeneration,d=selectedDifficulty,first=selected;try{await requestRanking(first,false,d)}catch{return}for(const stage of stages.map((_,i)=>i).filter(i=>i!==first)){await new Promise(r=>setTimeout(r,3000));if(generation!==rankingPreloadGeneration||view==='battle'||document.hidden)return;try{await requestRanking(stage,false,d)}catch{return}}};
clearRanking=function(s){$('clearRank').innerHTML='<h3>'+difficultyModes[s.difficulty].name+' · '+stages[s.stage].name+' TOP 25</h3><p>등록 없이 열람 가능 · 빠른 클리어 순, 동률이면 처치 수 순</p><form id="rankForm"><label for="rankNickname">닉네임 (2~16자)</label><div class="rank-input"><input id="rankNickname" name="nickname" autocomplete="nickname" placeholder="랭킹에 표시할 이름" minlength="2" maxlength="16" required><button id="rankSubmit" type="submit">클리어 등록</button></div><p id="rankStatus" role="status"></p></form><button id="browseRankings">전체 랭킹 보기</button><div id="clearRankRows"></div>';$('rankNickname').value=accountProfile?.nickname||'';loadRanking('clearRankRows',s.stage,false,s.difficulty);$('browseRankings').onclick=()=>$('rankingBtn').onclick();$('rankForm').onsubmit=async e=>{e.preventDefault();const r=await transact('rank',{finishId:s.finishId,nickname:$('rankNickname').value});if(r){$('rankStatus').textContent='등록 완료 · 더 빠른 기록일 때 갱신됩니다.';rankingCache.clear();await claimRankingTitles(false);loadRanking('clearRankRows',s.stage,true,s.difficulty)}}};
$('rankingBtn').onclick=()=>{if(view==='battle')pause();$('rankContent').innerHTML='<h2>작전 TOP 25</h2><div class="rank-filters"><label>난이도<select id="rankDifficulty">'+difficultyModes.map((m,i)=>'<option value="'+i+'">'+m.name+'</option>').join('')+'</select></label><label>지역<select id="rankStage">'+stages.map((s,i)=>'<option value="'+i+'">'+(i+1)+'. '+s.name+'</option>').join('')+'</select></label><label>무기<select id="rankWeapon"><option value="all">전체</option>'+weapons.map(w=>'<option value="'+w.id+'">'+w.name+'</option>').join('')+'</select></label></div><p>전체 플레이어 공유 · 등록 없이 열람 · 익스트림은 무기별 순위 제공</p><div id="rankRows"></div><button id="closeRanking">닫기</button>';$('rankDifficulty').value=String(selectedDifficulty);$('rankStage').value=String(selected);const load=()=>{const d=+$('rankDifficulty').value;$('rankWeapon').disabled=d!==2;if(d!==2)$('rankWeapon').value='all';loadRanking('rankRows',+$('rankStage').value,false,d,$('rankWeapon').value)};for(const id of ['rankDifficulty','rankStage','rankWeapon'])$(id).onchange=load;$('closeRanking').onclick=()=>$('rankModal').close();$('rankModal').showModal();load()};
const retry=document.createElement('button');retry.className='account-reconnect';retry.textContent='서버 연결 / 처리 확인';retry.onclick=syncAccount;$('saveNote').after(retry);
const rules=document.createElement('p');rules.className='market-server-note';rules.textContent='게임 골드 전용 · 드론 탐사는 제한시간이 없습니다. 결과 확인 후 귀환하거나 다음 구역에 도전하세요. 새로고침해도 이어집니다. 플린코는 정해진 결과로 자동 정산됩니다.';$('marketDescription').after(rules);
try{pendingOperation=JSON.parse(sessionStorage.getItem('sector09-v3-pending')||'null')}catch{}
renderCamp();persist();loadAssets().finally(()=>{updateAccountControls();setTimeout(preloadRankings,300)});syncAccount();
window.addEventListener('online',syncAccount);
